    try {
      return this.ok(new URL(argument));
    } catch {
      return this.error({
        parameter: argument,
        context,
        identifier: 'ArgumentHyperlinkInvalidURL',
        message: 'The argument did not resolve to a valid URL.'
      });
    }
  }
}
